export const legacyPrint: Record<string, LegacyPrint> = {"00-01":{"title":"PROLOGUE","category":"prologue","a":{"header":"Journal Entry","trigger":"","text":"Priorities: We need to complete the following mandatory objective:\n• Build 3 supply centers\n\nWe've barely got our heads around this mess, and yet we now find ourselves in charge. We're covering ourselves up and heading out on supply runs to see the front lines and gauge how bad things are.\n\nThings are going to get real very soon. The Hollow Men will tear down our supply centers almost as soon as we build them but we've got to start restoring our presence on the mainland.","footer":"Keep journal entries like this in the reserve in case you want to reference them in the future.","stopOrPause":""},"b":{"header":"PROLOGUE","trigger":"","text":"PLAY USING ALL THE RULES EXCEPT:\n• Do not open the Legacy deck.\n• Your character cannot get exposed.\n• You cannot do the Recon action.\n• You cannot do System-Wide Production when you play Produce Supplies cards.\n• Do not do Game End steps.\n\nWHEN YOU HAVE PLAYED THE PROLOGUE ENOUGH TIMES TO FEEL COMFORTABLE:\n• Destroy this card and the Prologue Objective card.\n• Open the Legacy deck.\n• Start your campaign.","footer":"","stopOrPause":"NONE"},"boxes":[]},"00-02":{"title":"Build 3 supply centers","category":"objective","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"MANDATORY OBJECTIVE","trigger":"","text":"Build 3 supply centers.\n\n0\n1\n2\n3","footer":"","stopOrPause":""},"boxes":[]},"01-01":{"title":"STOP","category":"legacy_stop","a":{"header":"STOP","trigger":"DRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN JANUARY.","text":"DO NOT DRAW, REVEAL, LOOK AT, HANDLE, OR OTHERWISE DISTURB THESE CARDS UNTIL INSTRUCTED.\n\nSTOP\n\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN JANUARY.","footer":"","stopOrPause":"STOP"},"b":{"header":"Journal Entry","trigger":"","text":"Priorities: Find our leaders.\nFind more supplies.\n\nAttached a document we found dated last year. It's grim. Our supplies won't last the year. Perhaps North America will give us clues; it's where the plague started. The Hollow Men are raiding surviving coastal cities and it's only a matter of time before they move inland. We need to recon before they do. Hope the people we meet know that we are there to help. Old prejudices last long.","footer":"Keep journal entries like this in the reserve in case you want to reference them in the future.","stopOrPause":""},"boxes":[]},"01-02":{"title":"October 15, Year 70","category":"legacy_archive","a":{"header":"KEEP DRAWING","trigger":"","text":"Be sure to read both sides of each card as you make your way through the Legacy deck.","footer":"","stopOrPause":"CONTINUE"},"b":{"header":"FROM THE ARCHIVES","trigger":"","text":"OCTOBER 15, YEAR 70\nDegradation of supplies and routes has reached critical level. We are no longer effective. Supply lines to the interior have been abandoned. Cities will fall within a year and, when they do, we will fall.\n\nNext year's stockpile projections are fatalistic. Haven leadership has voted to initiate the protocol we hoped would never come.","footer":"Keep papers like this in the reserve.","stopOrPause":""},"boxes":[]},"01-03":{"title":"NEW PRIORITIES","category":"legacy_instruction","a":{"header":"KEEP DRAWING","trigger":"","text":"From this point on in the Legacy deck, draw cards, reading both sides, until you hit a Pause or Stop card.\nRead Pause and Stop cards to find out when to start drawing again.\nIf you do not see Pause or Stop card, keep drawing.","footer":"","stopOrPause":"CONTINUE"},"b":{"header":"NEW PRIORITIES","trigger":"","text":"Our objectives follow.\nThis month we have 2 mandatory objectives.\nRemember you can always check to see how many objectives you need to complete for a given month by checking the objective calendar on the board.\n\nYEAR 71 OF THE FALL – 0\nPROLOGUE\nJANUARY\nFEBRUARY\nM\n36\n36\n33","footer":"","stopOrPause":""},"boxes":[]},"01-04":{"title":"Build 3 new supply centers","category":"objective","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"MANDATORY OBJECTIVE","trigger":"","text":"Build 3 new supply centers.\n\n0\n1\n2\n3","footer":"","stopOrPause":""},"boxes":[]},"01-05":{"title":"Recon North America","category":"objective","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"MANDATORY OBJECTIVE","trigger":"","text":"Recon North America.\n\nAdd this card to your pool of objectives.\nIf you complete it, but lose the first game in January, it counts as complete during your second game in January!","footer":"","stopOrPause":""},"boxes":[]},"01-06":{"title":"Forsaken Cities","category":"turning_point","a":{"header":"TURNING POINT","trigger":"","text":"This is your first Turning Point card.\nAfter reading it, place it into the Game End area.","footer":"","stopOrPause":"NONE"},"b":{"header":"Turning Point #1","trigger":"","text":"FORSAKEN CITIES\n\nIf there is at least one city with 0 population, open A 12 and destroy this card.\n\nPut this card into the Game End area each game until it is destroyed.","footer":"Put this card into the Game End area each game until it is destroyed.","stopOrPause":""},"boxes":[]},"01-07":{"title":"PAUSE","category":"legacy_pause","a":{"header":"PAUSE","trigger":"DRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 AT THE END OF YOUR FIRST GAME IN JANUARY.","text":"PAUSE\n\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 AT THE END OF YOUR FIRST GAME IN JANUARY.","footer":"","stopOrPause":"PAUSE"},"b":{"header":"","trigger":"","text":"New Rationed Event cards follow.\nKeep these cards in the reserve.\nThese add to the pool of Rationed Event cards you can select from at the beginning of each game.","footer":"","stopOrPause":""},"boxes":[]},"01-08":{"title":"Data Transfer","category":"rationed_event","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"RATIONED EVENT","trigger":"","text":"DATA TRANSFER\n\nTwo players (anywhere on the board) can swap 1 Player card from their hands.\n\nPlay at any time. Not an action.","footer":"Play at any time. Not an action.","stopOrPause":""},"boxes":[]},"01-09":{"title":"Dispersal","category":"rationed_event","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"RATIONED EVENT","trigger":"","text":"DISPERSAL\n\nMove 3 Supply cubes from one haven into one or more locations on the grid.\n\nPlay at any time. Not an action.","footer":"Play at any time. Not an action.","stopOrPause":""},"boxes":[]},"01-10":{"title":"Drastic Measures","category":"rationed_event","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"RATIONED EVENT","trigger":"","text":"DRASTIC MEASURES\n\nRemove up 2 Plague cubes from the grid.\n\nPlay at any time. Not an action.","footer":"Play at any time. Not an action.","stopOrPause":""},"boxes":[]},"01-11":{"title":"Extended Forecast","category":"rationed_event","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"RATIONED EVENT","trigger":"","text":"EXTENDED FORECAST\n\nDraw, look at, and rearrange the top 8 cards of the Infection deck. Put them back on top of the Infection deck.\n\nPlay at any time. Not an action.","footer":"Play at any time. Not an action.","stopOrPause":""},"boxes":[]},"02-01":{"title":"Perimeter Report","category":"legacy_stop","a":{"header":"STOP","trigger":"DRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN FEBRUARY.","text":"STOP\n\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN FEBRUARY.","footer":"","stopOrPause":"STOP"},"b":{"header":"PERIMETER REPORT","trigger":"","text":"If you have not opened 66, scratch the box below.\n\nDestroy this card after resolving it.","footer":"Destroy this card after resolving it.","stopOrPause":""},"boxes":[{"condition":"If you have not opened 66, scratch the box below.","revealed":"Our scouts report that the Hollow Men have raided North America. We quickly mobilized... but too late.\nOpen Package 1 and follow the instructions inside.(This does not complete any objectives.)\nDestroy the \"Decontamination Kit\" Unrationed Event card inside."}]},"02-02":{"title":"Journal Entry","category":"legacy_journal","a":{"header":"Journal Entry","trigger":"","text":"Hollow Men are expanding their raids now that our leaders and soldiers have disappeared. Our supply routes, already abandoned, are unsafe.\n\nThe Hollow Men are working their way into South America, likely looking for one of the labs working on a cure. They are also hitting our supply centers, which means building new ones.\n\nWe need to find a way to fortify these centers so they can resist their attacks.","footer":"","stopOrPause":"NONE"},"b":{"header":"FROM THE ARCHIVES","trigger":"","text":"APRIL 24, YEAR 40\nReports from the frontier havens. Hollow Men have breached them with help of local population who still distrust us. Sending security patrols but it might be too late. Not sure how well we will function without a full network of havens. Nearing the end of our projected timetable with no cure in sight.\n\nWe're going to start having to dilute supplies or abandon supply routes.","footer":"Keep papers like this in the reserve.","stopOrPause":""},"boxes":[]},"02-03":{"title":"NEW PRIORITIES","category":"legacy_instruction","a":{"header":"KEEP DRAWING","trigger":"","text":"Draw and read the other side of this card.","footer":"","stopOrPause":"CONTINUE"},"b":{"header":"NEW PRIORITIES","trigger":"","text":"DESTROY THE FOLLOWING OBJECTIVE:\n• RECON NORTH AMERICA\nNew objectives follow.\nWe still need to complete 2 objectives.\nRemember to place Supply cubes in the stockpile as shown on the projection calendar on the board (33 for February).\nAlso, as you complete months, you can cross them off the projected supplies calendar (on the board) to help you keep track of where you are in the campaign.","footer":"","stopOrPause":""},"boxes":[]},"02-04":{"title":"Recon 1 unknown region","category":"objective","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"OBJECTIVE","trigger":"","text":"Recon 1 unknown region.\n\nAdd this card to your pool of objectives.","footer":"","stopOrPause":""},"boxes":[]},"02-05":{"title":"Connect 2 new cities to the grid","category":"objective","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"OBJECTIVE","trigger":"","text":"Connect 2 new cities to the grid.\n\n0\n1\n2\n\nAdd this card to your pool of objectives.","footer":"","stopOrPause":""},"boxes":[]},"02-06":{"title":"Give Us the Tools and We Will Finish the Job!","category":"turning_point","a":{"header":"TURNING POINT","trigger":"","text":"After reading this turning point, place it into the Game End area.","footer":"","stopOrPause":"NONE"},"b":{"header":"Turning Point #2","trigger":"","text":"GIVE US THE TOOLS AND WE WILL FINISH THE JOB!\n\nIf you have lost 4 games in a row, scratch this box:\n\nPut this card into the Game End area each game until it is destroyed.","footer":"Put this card into the Game End area each game until it is destroyed.","stopOrPause":""},"boxes":[{"condition":"If you have lost 4 games in a row, scratch this box:","revealed":"Each game, during step 1 of setup, you may cross out a stockpile bonus below to add up to 10 Supply cubes from the reserve to the stockpile. Destroy this card after all 3 stockpile bonuses have been crossed out.\n\n10\n10\n10"}]},"02-07":{"title":"RIGHT NOW!","category":"legacy_pause","a":{"header":"PAUSE","trigger":"DRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 AT THE END OF YOUR FIRST GAME IN FEBRUARY.","text":"PAUSE\n\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 AT THE END OF YOUR FIRST GAME IN FEBRUARY.","footer":"","stopOrPause":"PAUSE"},"b":{"header":"RIGHT NOW!","trigger":"","text":"Open the following door:\n34","footer":"","stopOrPause":""},"boxes":[]},"02-08":{"title":"Hidden Stockpile","category":"rationed_event","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"RATIONED EVENT","trigger":"","text":"HIDDEN STOCKPILE\n\nTake up to 6 Supply cubes from the reserve and add them to a location containing a player pawn.\n\nPlay at any time. Not an action.","footer":"Play at any time. Not an action.","stopOrPause":""},"boxes":[]},"02-09":{"title":"It Worked the First Time","category":"rationed_event","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"RATIONED EVENT","trigger":"","text":"IT WORKED THE FIRST TIME\n\nTake 1 Rationed Event card from the discard pile and play it immediately.\n\nPlay at any time. Not an action.","footer":"Play at any time. Not an action.","stopOrPause":""},"boxes":[]},"02-10":{"title":"EXTENDED TIME","category":"rationed_event","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"RATIONED EVENT","trigger":"","text":"EXTENDED TIME\n\nThe current player gains 3 actions.","footer":"Play during any player's \"Actions\" step. Not an action.","stopOrPause":""},"boxes":[]},"03-01":{"title":"PERIMETER REPORT","category":"legacy_stop","a":{"header":"STOP","trigger":"Draw this card and read the other side during step 2 of the setup of your first game in March.","text":"STOP\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN MARCH.","footer":"","stopOrPause":"STOP"},"b":{"header":"PERIMETER REPORT","trigger":"","text":"If you have not opened 67, scratch the first box below.","footer":"Destroy this card after resolving it.","stopOrPause":""},"boxes":[{"condition":"First box scratched because 67 was still sealed. Second box still covered.","revealed":"It's critical that we Recon South America soon–before the Hollow Men sabotage anything important."},{"condition":"Both boxes scratched. The second box was not part of the instruction.","revealed":"It's critical that we Recon South America soon–before the Hollow Men sabotage anything important.\n\nWe didn't tell you to scratch this box."}]},"03-02":{"title":"Journal Entry","category":"legacy_journal","a":{"header":"Journal Entry","trigger":"","text":"Havens have been in trouble for a while. Old records (attached) show that the four main labs were never meant to go beyond 50 years. Nor were the supplies. Our leaders have been putting on a good show for a long time now. They knew the end was near. Now they are gone and it's a race between us and the Hollow Men.\n\nWe need to find the havens outside the Atlantic... they might have supplies or equipment we can use.","footer":"","stopOrPause":"NONE"},"b":{"header":"FROM THE ARCHIVES","trigger":"","text":"YEAR 57 SUMMARY\n\nPEARL was on the verge of a cure when it went silent.\n\nOPAL, JADE, and TOPAZ are set up to support PEARL – they are not equipped to find a cure on their own.\n\nTransporting a potential cure from PEARL to JADE was always going to be a frantic dash. We must keep the routes between them viable.","footer":"Keep papers like this in the reserve.","stopOrPause":""},"boxes":[]},"03-03":{"title":"NEW PRIORITIES","category":"legacy_instruction","a":{"header":"KEEP DRAWING","trigger":"Draw and read the other side of this card.","text":"KEEP DRAWING\nDraw and read the other side of this card.","footer":"","stopOrPause":"CONTINUE"},"b":{"header":"NEW PRIORITIES","trigger":"","text":"We now need to complete 3 objectives each month.\n\nUse the objective calendar on the board to help you remember how many objectives you need to complete each month.\n\nCalendar illustration, left edge cropped. Visible header: \"IE FALL – OBJECTIVES AND\". FEBRUARY: two stars, 33. MARCH: three stars, 30 (column outlined). APRIL: three stars, 27. The next column is cut off and shows one star.","footer":"","stopOrPause":""},"boxes":[]},"03-04":{"title":"Complete 2 searches","category":"objective","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"OBJECTIVE","trigger":"","text":"Complete 2 searches.","footer":"Add this card to your pool of objectives.","stopOrPause":""},"boxes":[]},"03-05":{"title":"Access a lost haven","category":"objective","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"OBJECTIVE","trigger":"","text":"Access a lost haven.","footer":"Add this card to your pool of objectives. Destroy it at the end of the game in which you complete the objective.","stopOrPause":""},"boxes":[]},"03-06":{"title":"RIGHT NOW!","category":"legacy_pause","a":{"header":"PAUSE","trigger":"Draw this card and read the other side during step 2 at the end of your first game in March.","text":"PAUSE\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 AT THE END OF YOUR FIRST GAME IN MARCH.","footer":"","stopOrPause":"PAUSE"},"b":{"header":"RIGHT NOW!","trigger":"","text":"Open the following doors:\nK    24    47    E","footer":"","stopOrPause":""},"boxes":[]},"03-07":{"title":"EPIDEMIC","category":"epidemic","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"EPIDEMIC","trigger":"","text":"1-INCREASE\nMove the Infection Rate marker forward 1 space.\n\n2-INFECT\nDraw the bottom card from the Infection deck and remove all the Supply cubes (if any) from that city. Discard that card.\n\n3-INTENSIFY\nShuffle the cards in the Infection discard pile and put them on top of the Infection deck.","footer":"","stopOrPause":""},"boxes":[]},"03-08":{"title":"EPIDEMIC","category":"epidemic","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"EPIDEMIC","trigger":"","text":"1-INCREASE\nMove the Infection Rate marker forward 1 space.\n\n2-INFECT\nDraw the bottom card from the Infection deck and remove all the Supply cubes (if any) from that city. Discard that card.\n\n3-INTENSIFY\nShuffle the cards in the Infection discard pile and put them on top of the Infection deck.","footer":"","stopOrPause":""},"boxes":[]},"03-09":{"title":"EPIDEMIC","category":"epidemic","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"EPIDEMIC","trigger":"","text":"1-INCREASE\nMove the Infection Rate marker forward 1 space.\n\n2-INFECT\nDraw the bottom card from the Infection deck and remove all the Supply cubes (if any) from that city. Discard that card.\n\n3-INTENSIFY\nShuffle the cards in the Infection discard pile and put them on top of the Infection deck.","footer":"","stopOrPause":""},"boxes":[]},"03-10":{"title":"EPIDEMIC","category":"epidemic","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"EPIDEMIC","trigger":"","text":"1-INCREASE\nMove the Infection Rate marker forward 1 space.\n\n2-INFECT\nDraw the bottom card from the Infection deck and remove all the Supply cubes (if any) from that city. Discard that card.\n\n3-INTENSIFY\nShuffle the cards in the Infection discard pile and put them on top of the Infection deck.","footer":"","stopOrPause":""},"boxes":[]},"03-11":{"title":"EPIDEMIC","category":"epidemic","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"EPIDEMIC","trigger":"","text":"1-INCREASE\nMove the Infection Rate marker forward 1 space.\n\n2-INFECT\nDraw the bottom card from the Infection deck and remove all the Supply cubes (if any) from that city. Discard that card.\n\n3-INTENSIFY\nShuffle the cards in the Infection discard pile and put them on top of the Infection deck.","footer":"","stopOrPause":""},"boxes":[]},"04-01":{"title":"PERIMETER REPORT","category":"legacy_stop","a":{"header":"STOP","trigger":"Draw this card and read the other side during step 2 of the setup of your first game in April.","text":"STOP\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN APRIL.","footer":"","stopOrPause":"STOP"},"b":{"header":"PERIMETER REPORT","trigger":"","text":"If you have not opened 67 (South America), scratch the box below.","footer":"Destroy this card after resolving it.","stopOrPause":""},"boxes":[{"condition":"Box scratched because 67 (South America) was still sealed.","revealed":"Our scouts report that the Hollow Men have raided South America. We quickly mobilized... but too late.\n\nOpen Package 5 and follow the instructions inside. (This does not complete any objectives.)\n\nDestroy the \"Strategic Reserves\" Unrationed Event card inside."}]},"04-02":{"title":"Journal Entry","category":"legacy_journal","a":{"header":"Journal Entry","trigger":"","text":"This year is already taking its toll. People and resources are getting stretched thin. Gearing up to be out in the world is mentally difficult as we're outsiders there. One bright spot are the laboratories. Although they lost their lead lab, the three labs in the Southern Hemisphere have kept working through the generations. We need to find out if they've made any progress.","footer":"","stopOrPause":"NONE"},"b":{"header":"FROM THE ARCHIVES","trigger":"","text":"YEAR 42\n\nPacific Haven not reporting. Hoping Hollow Men did not steal everything. Sending scouts to Lima to check. Also sending patrols to Indian Haven... silent since the fallout in Indian Ocean. Presumed lost.\n\nHandwritten coordinate slip, torn at the end of the last line:\nJ  26°11'28\"S  28°02'43\"E\nO  34°29'38\"S  58°31'35\"W\nT  41°11'46\"S  174°56'29\"E\nP  53°19'21\"N  1","footer":"Keep papers like this in the reserve.","stopOrPause":""},"boxes":[]},"04-03":{"title":"RIGHT NOW!","category":"legacy_pause","a":{"header":"PAUSE","trigger":"Draw this card and read the other side during step 2 at the end of your first game in April.","text":"PAUSE\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 AT THE END OF YOUR FIRST GAME IN APRIL.","footer":"","stopOrPause":"PAUSE"},"b":{"header":"RIGHT NOW!","trigger":"","text":"Open the following door:\n42","footer":"","stopOrPause":""},"boxes":[]},"05-01":{"title":"PERIMETER REPORT","category":"legacy_stop","a":{"header":"STOP","trigger":"Draw this card and read the other side during step 2 of the setup of your first game in May.","text":"STOP\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN MAY.","footer":"","stopOrPause":"STOP"},"b":{"header":"PERIMETER REPORT","trigger":"","text":"If you have not opened 60, scratch the box below.","footer":"Destroy this card after resolving it.","stopOrPause":""},"boxes":[{"condition":"Box scratched because 60 was still sealed.","revealed":"We have found records from 25 years ago showing the location of a now-fallen haven. It contained the equipment to generate supplies and was about to field test inoculating against the plague! We now know where it is. It is vital we access it.\n\nOpen 60 and put it on the board. You have not yet accessed this haven."}]},"05-02":{"title":"Journal Entry","category":"legacy_journal","a":{"header":"Journal Entry","trigger":"","text":"Hollow Men have left the Americas alone and seem to be moving (retreating?) into Europe and Africa. They stop at nothing. Wherever they go, the plague follows. They are like men possessed to end everything we're trying to do. After 70 years, old prejudices still exist.\n\nAlso, we've learned where our leaders went.\n\nAnd why we're still here.","footer":"","stopOrPause":"NONE"},"b":{"header":"FROM THE ARCHIVES","trigger":"","text":"NOVEMBER 5, YEAR 70\n\nInitiating the protocol during our annual leadership summit. It's a long journey to Utopia. We are the best and brightest minds of the havens and feel confident that Utopia will take us in, despite our differences. We have knowledge, skills, and experience. We can help. Those we leave behind would not gain access to Utopia.\n\nThe list is made. Not an easy task but necessary. Godspeed us on our journey.","footer":"Keep papers like this in the reserve.","stopOrPause":""},"boxes":[]},"05-03":{"title":"RIGHT NOW!","category":"legacy_pause","a":{"header":"PAUSE","trigger":"Draw this card and read the other side during step 2 at the end of your first game in May.","text":"PAUSE\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 AT THE END OF YOUR FIRST GAME IN MAY.","footer":"","stopOrPause":"PAUSE"},"b":{"header":"RIGHT NOW!","trigger":"","text":"Open the following doors:\n31    36","footer":"","stopOrPause":""},"boxes":[]},"06-01":{"title":"PERIMETER REPORT","category":"legacy_stop","a":{"header":"STOP","trigger":"Draw this card and read the other side during step 2 of the setup of your first game in June.","text":"STOP\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN JUNE.","footer":"","stopOrPause":"STOP"},"b":{"header":"PERIMETER REPORT","trigger":"","text":"If you have not opened 64 (Europe), scratch the box below.","footer":"Destroy this card after resolving it.","stopOrPause":""},"boxes":[{"condition":"Box scratched because 64 (Europe) was still sealed.","revealed":"Our scouts report that the Hollow Men have raided Europe. We quickly mobilized... but too late.\n\nOpen Package 4 and follow the instructions inside. (This does not complete any objectives.)\n\nDestroy the \"Relocation\" Unrationed Event card inside.\n\nThen, open 21."}]},"06-02":{"title":"Journal Entry","category":"legacy_journal","a":{"header":"Journal Entry","trigger":"","text":"Utopia. Can we reach them?\n\nOur leaders went there. It's the last true piece of civilization left—secure enough to resist both the plague and the Hollow Men. Perhaps they have a cure? We don't know exactly where Utopia is. Somewhere in the far east.\n\nIf we can get there, some think they would help us. Some think they would kill us on sight.","footer":"","stopOrPause":"NONE"},"b":{"header":"FROM THE ARCHIVES","trigger":"","text":"MAY 23, YEAR 14 AFTER THE FALL\n\nA new problem – an organized militia has started attacking our supply routes. They seem to be normal humans but somehow dead inside. Military Director Yona has dubbed them the \"Hollow Men\" because of their \"violent souls.\" They have made our thankless task almost impossible as they have no love for us. We have stepped up patrols and have gotten the upper hand for now.","footer":"Keep papers like this in the reserve.","stopOrPause":""},"boxes":[]},"06-03":{"title":"RIGHT NOW!","category":"legacy_pause","a":{"header":"PAUSE","trigger":"Draw this card and read the other side during step 2 at the end of your first game in June.","text":"PAUSE\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 AT THE END OF YOUR FIRST GAME IN JUNE.","footer":"","stopOrPause":"PAUSE"},"b":{"header":"RIGHT NOW!","trigger":"","text":"NEW VOLUNTEERS FROM THE HAVENS HAVE DECIDED TO JOIN US.\n\nOpen the following doors:\n44    49","footer":"","stopOrPause":""},"boxes":[]},"06-04":{"title":"INOCULATION UNIT","category":"rationed_event","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"RATIONED EVENT","trigger":"","text":"INOCULATION UNIT\n\nPut up to 3 Infection cards from the Infection discard pile into Package 6.\n\nYou may play this card between step 2 and step 3 of an epidemic.","footer":"Play at any time. Not an action.","stopOrPause":""},"boxes":[]},"06-05":{"title":"Expeditionary Voyage","category":"rationed_event","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"RATIONED EVENT","trigger":"","text":"EXPEDITIONARY VOYAGE\n\nThe current player may do the Chart Sea Lane action for free. (Do not spend an action or any Supply cubes.)\n\nThe sea lane may cross any number of red region lines.\n\nPlay at any time. Not an action.","footer":"Play at any time. Not an action.","stopOrPause":""},"boxes":[]},"07-01":{"title":"PERIMETER REPORT","category":"legacy_stop","a":{"header":"STOP","trigger":"Draw this card and read the other side during step 2 of the setup of your first game in July.","text":"STOP\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN JULY.","footer":"","stopOrPause":"STOP"},"b":{"header":"PERIMETER REPORT","trigger":"","text":"If you have not opened 57 (Africa), scratch the box below.","footer":"Destroy this card after resolving it.","stopOrPause":""},"boxes":[{"condition":"Box scratched because 57 (Africa) was still sealed.","revealed":"Our scouts report that the Hollow Men have raided Africa. We quickly mobilized... but too late.\n\nOpen Package 7 and follow the instructions inside. (This does not complete any objectives.)\n\nDestroy the \"TOPAZ Experimental Vaccine\" Unrationed Event card inside."}]},"07-02":{"title":"Journal Entry","category":"legacy_journal","a":{"header":"Journal Entry","trigger":"","text":"Satellite towers have started picking up faint broadcast signals. Need to know who is transmitting. We think it’s Hollow Men, but there’s someone else. Could the Hollow Men be taking orders?\n\nIs someone ordering them to spread the plague?\n\nThe grid is growing and can’t handle Hollow Men spreading the plague. We’re prepared to forsake some if need be. Would that make us the monsters the world thinks we are?","footer":"","stopOrPause":"NONE"},"b":{"header":"FROM THE ARCHIVES","trigger":"","text":"JULY, YEAR 38\n\nHaven networks still at full capacity – when we were re-located here, they set us up properly. Hope is still kindled. Strange to see adults on the havens who never knew the world before. I dream to live on land again. I sometimes dream of fleeing for Utopia. I imagine they still function like the old world. I miss land and dirt. I hear they are close to a cure. Would they share it with our people?","footer":"Keep papers like this in the reserve.","stopOrPause":""},"boxes":[]},"07-03":{"title":"Triangulate signals.","category":"objective","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"OBJECTIVE","trigger":"","text":"Triangulate signals.\n\nThis objective is completed when a blue city, a yellow city, and a black city each contain a satellite tower.\n\nWhen you complete this objective, open door 35.\n\nAdd this card to your pool of objectives. Destroy it at the end of the game in which you complete the objective.","footer":"Add this card to your pool of objectives. Destroy it at the end of the game in which you complete the objective.","stopOrPause":""},"boxes":[]},"08-01":{"title":"PERIMETER REPORT","category":"legacy_stop","a":{"header":"STOP","trigger":"Draw this card and read the other side during step 2 of the setup of your first game in August.","text":"STOP\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN AUGUST.","footer":"","stopOrPause":"STOP"},"b":{"header":"PERIMETER REPORT","trigger":"","text":"If you have not opened 62 (the Middle East), scratch the box below.","footer":"Destroy this card after resolving it.","stopOrPause":""},"boxes":[{"condition":"Box scratched because 62 (the Middle East) was still sealed.","revealed":"Our scouts report that the Hollow Men have raided the Middle East. We quickly mobilized... but too late.\n\nOpen Package 2 and follow the instructions inside. (This does not complete any objectives.)\n\nDestroy the \"Renewal\" Unrationed Event card inside."}]},"08-02":{"title":"Journal Entry","category":"legacy_journal","a":{"header":"Journal Entry","trigger":"","text":"Have finally fully accessed the satellite towers. Starting to monitor different frequencies. Whoever is broadcasting uses multiple channels. We’ve lost a lot of time listening to these decoy stations.\n\nAccessing the towers has given us a sense of purpose. We feel invigorated!\n\nImmediately spend up to 3 production units on character abilities. Finish spending these before step 3 of setup (Supply the Grid).","footer":"","stopOrPause":"NONE"},"b":{"header":"FROM THE ARCHIVES","trigger":"","text":"DECEMBER 19, YEAR 48\n\nThe three labs in the Southern Hemisphere have made limited advancements, but perhaps too late as PEARL has stopped reporting. Their last broadcast said they had found what they needed!\n\nThe sediment cores contained bacteria samples in which they had identified the bacteriophage. We had it! We had a means to a cure. Now they are gone. Sending a team to investigate. They are covered properly to avoid attention.","footer":"Keep papers like this in the reserve.","stopOrPause":""},"boxes":[]},"08-03":{"title":"RIGHT NOW!","category":"legacy_instruction","a":{"header":"KEEP DRAWING","trigger":"","text":"Draw and read the other side of this card.","footer":"","stopOrPause":"CONTINUE"},"b":{"header":"RIGHT NOW!","trigger":"","text":"Open the following doors:\nM    25","footer":"","stopOrPause":""},"boxes":[]},"08-04":{"title":"Frequency Scanner","category":"frequency_scanner","a":{"header":"FREQUENCY SCANNER","trigger":"","text":"It's time to start listening...\n\nThe Frequency Scanner is on the other side of this card. You'll use this card whenever you do the Monitor action.\n\nKeep this card in the reserve between games.","footer":"","stopOrPause":"NONE"},"b":{"header":"FREQUENCY SCANNER","trigger":"","text":"When you do the Monitor action, scratch a box, then refer to the text below.\n\nIF YOU REVEAL:\nAn orange square: Open the dossier door.\nA white square: Take 1 or 2 cards from the top of the Player discard pile and add them to your hand. (You may not take Epidemic cards.)\n\nTen boxes, bottom (low) to top (high): 8.24, 8.81, 9.1, 9.2, 9.31, 9.58, 9.75, 10.31, 10.57, 11.88.","footer":"","stopOrPause":""},"boxes":[{"condition":"The 8.24 box, the bottom box, is scratched. The other nine stay covered in this photo.","revealed":"8.24 reveals the white square: take 1 or 2 cards from the top of the Player discard pile and add them to your hand. You may not take Epidemic cards."},{"condition":"The 8.81 box is scratched. The other nine stay covered in this photo.","revealed":"8.81 reveals the white square: take 1 or 2 cards from the top of the Player discard pile and add them to your hand. You may not take Epidemic cards."},{"condition":"The 9.1 box is scratched. The other nine stay covered in this photo.","revealed":"9.1 reveals the white square: take 1 or 2 cards from the top of the Player discard pile and add them to your hand. You may not take Epidemic cards."},{"condition":"The 9.2 box is scratched. The other nine stay covered in this photo.","revealed":"9.2 reveals an orange sticker numbered 52. Open dossier door 52."},{"condition":"The 9.31 box is scratched. The other nine stay covered in this photo.","revealed":"9.31 reveals the white square: take 1 or 2 cards from the top of the Player discard pile and add them to your hand. You may not take Epidemic cards."},{"condition":"The 9.58 box is scratched. The other nine stay covered in this photo.","revealed":"9.58 reveals the white square: take 1 or 2 cards from the top of the Player discard pile and add them to your hand. You may not take Epidemic cards."},{"condition":"The 9.75 box is scratched. The other nine stay covered in this photo.","revealed":"9.75 reveals the white square: take 1 or 2 cards from the top of the Player discard pile and add them to your hand. You may not take Epidemic cards."},{"condition":"The 10.31 box is scratched. The other nine stay covered in this photo.","revealed":"10.31 reveals the white square: take 1 or 2 cards from the top of the Player discard pile and add them to your hand. You may not take Epidemic cards."},{"condition":"The 10.57 box is scratched. The other nine stay covered in this photo.","revealed":"10.57 reveals the white square: take 1 or 2 cards from the top of the Player discard pile and add them to your hand. You may not take Epidemic cards."},{"condition":"The 11.88 box, the top box, is scratched. The other nine stay covered in this photo.","revealed":"11.88 reveals an orange sticker numbered 43. Open dossier door 43."}]},"08-05":{"title":"RIGHT NOW!","category":"legacy_pause","a":{"header":"PAUSE","trigger":"Draw this card and read the other side during step 2 at the end of your first game in August.","text":"PAUSE\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 AT THE END OF YOUR FIRST GAME IN AUGUST.","footer":"","stopOrPause":"PAUSE"},"b":{"header":"RIGHT NOW!","trigger":"","text":"Open the following doors:\n29    48","footer":"","stopOrPause":""},"boxes":[]},"09-01":{"title":"PERIMETER REPORT","category":"legacy_stop","a":{"header":"STOP","trigger":"Draw this card and read the other side during step 2 of the setup of your first game in September.","text":"STOP\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN SEPTEMBER.","footer":"","stopOrPause":"STOP"},"b":{"header":"PERIMETER REPORT","trigger":"","text":"If you have not opened 65, scratch the box below.","footer":"Destroy this card after resolving it.","stopOrPause":""},"boxes":[{"condition":"Box scratched because 65 was still sealed.","revealed":"We've finally located another lost haven. We still need to get to it but now, at least, we know where to go.\n\nOpen 65 and place it on the board. You have not yet accessed this haven."}]},"09-02":{"title":"Journal Entry","category":"legacy_journal","a":{"header":"Journal Entry","trigger":"","text":"PEARL and its possible cure is all we have left. We need this. The year is drawing to a close and this is our last chance. We need to find it. We need to get it. We need to start making a cure. What are Utopia’s motives? Are they holding PEARL hostage?","footer":"","stopOrPause":"NONE"},"b":{"header":"FROM THE ARCHIVES","trigger":"","text":"APRIL 15, YEAR 44\n\nTwo of our havens are gone. Without their supplies, our ability to continue has been severely compromised. I feel the first real tendrils of despair entering my heart.\n\nIs someone so depraved that they would let us all die? We were condemned to these havens, but we have made every effort to help the whole world. If we were gone, then what?","footer":"Keep papers like this in the reserve.","stopOrPause":""},"boxes":[]},"09-03":{"title":"NEW PRIORITIES","category":"legacy_instruction","a":{"header":"KEEP DRAWING","trigger":"","text":"Draw and read the other side of this card.","footer":"","stopOrPause":"CONTINUE"},"b":{"header":"NEW PRIORITIES","trigger":"","text":"DESTROY THE FOLLOWING OBJECTIVE:\n• RECON 1 UNKNOWN REGION\n\nThe \"Recon East Asia\" objective is enclosed. If you have already Reconned East Asia, count this objective as complete during September!\n\nRIGHT NOW!\nOpen the following doors:\nR    55    D    Y    U","footer":"","stopOrPause":""},"boxes":[]},"09-04":{"title":"Recon East Asia.","category":"objective","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"MANDATORY OBJECTIVE","trigger":"","text":"Recon East Asia.\n\nAdd this card to your pool of objectives. If you complete it, but lose the first game in September, it counts as complete during your second game in September!","footer":"Add this card to your pool of objectives. If you complete it, but lose the first game in September, it counts as complete during your second game in September!","stopOrPause":""},"boxes":[]},"09-05":{"title":"RIGHT NOW!","category":"legacy_pause","a":{"header":"PAUSE","trigger":"Draw this card and read the other side during step 2 at the end of your first game in September.","text":"PAUSE\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 AT THE END OF YOUR FIRST GAME IN SEPTEMBER.","footer":"","stopOrPause":"PAUSE"},"b":{"header":"RIGHT NOW!","trigger":"","text":"Open the following door:\n33","footer":"","stopOrPause":""},"boxes":[]},"09-06":{"title":"Cautious Approach","category":"rationed_event","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"RATIONED EVENT","trigger":"","text":"CAUTIOUS APPROACH\n\nThe current player draws the next 4 Player cards, adding any City cards to their hand. Discard any other cards to the Player discard pile without effect.\n\nPlay at any time. Not an action.","footer":"Play at any time. Not an action.","stopOrPause":""},"boxes":[]},"10-01":{"title":"PERIMETER REPORT","category":"legacy_stop","a":{"header":"STOP","trigger":"Draw this card and read the other side during step 2 of the setup of your first game in October.","text":"STOP\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN OCTOBER.","footer":"","stopOrPause":"STOP"},"b":{"header":"PERIMETER REPORT","trigger":"","text":"If you have not opened 56 and 63 (East Asia), scratch the box below.","footer":"Destroy this card after resolving it.","stopOrPause":""},"boxes":[{"condition":"Box scratched because 56 and 63 (East Asia) were not both open.","revealed":"We led a desperate strike force to find a path to Asia. Found one at great cost. Do the following:\n\n• Open Package 3 and follow the instructions inside. (This does not complete any objectives.)\n• After selecting characters for this game, add a scar to 1 of these characters.\n• Destroy the \"Biodome Prototype\" Unrationed Event card inside."}]},"10-02":{"title":"Journal Entry","category":"legacy_journal","a":{"header":"Journal Entry","trigger":"","text":"So far from our homes. So much chaos. So much hatred toward us. Even still. Not sure how much longer we can do this. Not sure humanity is worth it.\n\nStill, we have found a way to use the satellite towers against the Hollow Men. By broadcasting on their frequencies, we can lead them astray, which should help us move around more freely.\n\nIf we get them onto our havens, we think we can persuade some of them to join our cause.","footer":"","stopOrPause":"NONE"},"b":{"header":"FROM THE ARCHIVES","trigger":"","text":"OCTOBER, YEAR 1\n\nFive months on these \"havens.\" I understand why, but I still miss home. We hear stories of a plague on the mainland. If the world collapses, can we leave? I hope my children will soon return to the home we left.\n\nI left a note there for them to read when we return. For now, they cry every night, but soon all will feel normal... as normal as it can be.","footer":"Keep papers like this in the reserve.","stopOrPause":""},"boxes":[]},"10-03":{"title":"NEW PRIORITIES","category":"legacy_instruction","a":{"header":"KEEP DRAWING","trigger":"","text":"Draw and read the other side of this card.","footer":"","stopOrPause":"CONTINUE"},"b":{"header":"NEW PRIORITIES","trigger":"","text":"DESTROY THE FOLLOWING OBJECTIVES:\n• RECON EAST ASIA\n• CONNECT 2 NEW CITIES\n• COMPLETE 2 SEARCHES\n\nA new mandatory objective is enclosed. We need to complete 2 objectives this month.\n\nChart, with no further caption on the card:\nSEPTEMBER: 3 stars, 12\nOCTOBER: 2 stars, 8\nNOVEMBER: 1 star, 4\n\nOpen the following doors:\nP    37","footer":"","stopOrPause":""},"boxes":[]},"10-04":{"title":"Get Hollow Men to defect.","category":"objective","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"MANDATORY OBJECTIVE","trigger":"","text":"Get Hollow Men to defect.\n\nThis objective is completed when there is at least 1 Hollow Men figure on 3 different havens.\n\nAdd this card to your pool of objectives. If you complete it, but lose the first game in October, it counts as complete during your second game in October!","footer":"Add this card to your pool of objectives. If you complete it, but lose the first game in October, it counts as complete during your second game in October!","stopOrPause":""},"boxes":[]},"10-05":{"title":"Hollow Men Have Defected","category":"turning_point","a":{"header":"TURNING POINT","trigger":"","text":"After reading this turning point, place it into the Game End area.","footer":"","stopOrPause":"NONE"},"b":{"header":"Turning Point #3","trigger":"","text":"HOLLOW MEN HAVE DEFECTED\n\nIf there is at least 1 Hollow Men figure on 3 different havens at the end of the game, open door 17 and destroy this card.\n\nPut this card into the Game End area each game until it is destroyed.","footer":"Put this card into the Game End area each game until it is destroyed.","stopOrPause":""},"boxes":[]},"10-06":{"title":"Right Now!","category":"legacy_pause","a":{"header":"PAUSE","trigger":"DRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 AT THE END OF YOUR FIRST GAME IN OCTOBER.","text":"PAUSE\n\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 AT THE END OF YOUR FIRST GAME IN OCTOBER.","footer":"","stopOrPause":"PAUSE"},"b":{"header":"RIGHT NOW!","trigger":"","text":"Open the following doors:\n28\n45","footer":"","stopOrPause":""},"boxes":[]},"10-07":{"title":"Mobile Shelters","category":"rationed_event","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"RATIONED EVENT","trigger":"","text":"MOBILE SHELTERS\n\nBuild 2 shelters anywhere on the grid for free.\n\nPlay at any time. Not an action.","footer":"Play at any time. Not an action.","stopOrPause":""},"boxes":[]},"11-01":{"title":"Intelligence Report","category":"legacy_stop","a":{"header":"STOP","trigger":"DRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN NOVEMBER.","text":"STOP\n\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN NOVEMBER.","footer":"","stopOrPause":"STOP"},"b":{"header":"INTELLIGENCE REPORT","trigger":"","text":"If Hollow Men have not yet defected, scratch the box below.\n\nDestroy this card after resolving it.","footer":"Destroy this card after resolving it.","stopOrPause":""},"boxes":[{"condition":"If Hollow Men have not yet defected, scratch the box below.","revealed":"We've gotten them to turn, but at great cost.\nOpen door 17 and follow the instructions inside. (This does not complete any objectives.)\nThen, after selecting characters for this game, add a scar to 2 of these characters."}]},"11-02":{"title":"Journal Entry","category":"legacy_journal","a":{"header":"Journal Entry","trigger":"","text":"This is our month. Every November, Utopia releases new Hollow Men into the world. For two days, they are distracted. Our recon into the city needs to happen this month or we’ll miss our opportunity. We don’t know what we’ll find in there or what we’ll find at PEARL. We need to be prepared for anything.","footer":"","stopOrPause":"NONE"},"b":{"header":"FROM THE ARCHIVES","trigger":"","text":"JUNE 18, YEAR 10\n\n10 years upon the seas. 5 years toward a cure. Some on the havens still don’t want to help the world, after they had quarantined us here. I understand though. No one knew the long-term effects of COdA. Our minds are ours again, but our skin is forever faded. Even our children are born faded. These havens proved to be a godsend as we were isolated when the plague struck. Our prison became humanity’s last hope.","footer":"Keep papers like this in the reserve.","stopOrPause":""},"boxes":[]},"11-03":{"title":"New Priorities","category":"legacy_instruction","a":{"header":"KEEP DRAWING","trigger":"","text":"Draw and read the other side of this card.","footer":"","stopOrPause":"CONTINUE"},"b":{"header":"NEW PRIORITIES","trigger":"","text":"DESTROY THE FOLLOWING OBJECTIVES:\n• BUILD 3 NEW SUPPLY CENTERS\n• GET HOLLOW MEN TO DEFECT\n\nA new mandatory objective is enclosed.\nWe only need to complete this 1 objective in November.\n\nCalendar: OCTOBER 2 stars, 8. NOVEMBER 1 star, 4. DECEMBER 1 star, 0.","footer":"","stopOrPause":""},"boxes":[]},"11-04":{"title":"Complete the Plan","category":"objective","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"MANDATORY OBJECTIVE","trigger":"","text":"Complete the Plan.\n\nAdd this card to your pool of objectives. Destroy it at the end of the game in which you complete the objective.","footer":"Add this card to your pool of objectives. Destroy it at the end of the game in which you complete the objective.","stopOrPause":""},"boxes":[]},"11-05":{"title":"The Plan","category":"plan","a":{"header":"THE PLAN","trigger":"","text":"The Hollow Men gave us inside information to help us access Utopia. We’ve finalized our plan.\n\nDestroy the An Incomplete Plan card. The Plan is on the other side of this card and contains four steps that may be done in any order. When a step is complete, check its box. Any boxes checked carry over to future games.\n\nWhen all boxes are checked, open Package 8 (you have completed the plan). Keep this card in the reserve between games.","footer":"","stopOrPause":"NONE"},"b":{"header":"The Plan","trigger":"","text":"Do the Recon action in Shanghai with the cards indicated below to check off a part of the plan.\nA supply center is not required to do this.\n\n• Locate hidden entrance — red A, B, C, D, E\n• Decode access key — black A, B, C, D\n• Devise distraction — yellow A, B, C\n• Prepare containment units — blue A, B, C\n\nWhen everything is checked, you have completed the plan.\nOpen Package 8 and destroy this card.","footer":"","stopOrPause":""},"boxes":[]},"12-01":{"title":"Perimeter Report","category":"legacy_stop","a":{"header":"STOP","trigger":"DRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN DECEMBER.","text":"STOP\n\nDRAW THIS CARD AND READ THE OTHER SIDE DURING STEP 2 OF THE SETUP OF YOUR FIRST GAME IN DECEMBER.","footer":"","stopOrPause":"STOP"},"b":{"header":"PERIMETER REPORT","trigger":"","text":"If you have not completed the plan, scratch the box below.\n\nDestroy this card after resolving it.","footer":"Destroy this card after resolving it.","stopOrPause":""},"boxes":[{"condition":"If you have not completed the plan, scratch the box below.","revealed":"The new Hollow Men turned on Utopia, rising up to aid our cause!\nOpen Package 8 and follow the instructions inside. (This does not complete any objectives.)\nDestroy the \"Riot Control\" Unrationed Event card inside."}]},"12-02":{"title":"Journal Entry","category":"legacy_journal","a":{"header":"Journal Entry","trigger":"","text":"Our supplies are almost gone. We have come so close. We’ve reconnected the world. Now we hope to cure it. We must reach Lake Baikal, find the PEARL Lab, get whatever cure they have created, and bring it to Johannesburg.\n\nWe won’t have this opportunity again.\n\nIf we don’t do it this month, then all is lost.","footer":"","stopOrPause":"NONE"},"b":{"header":"FROM THE ARCHIVES","trigger":"","text":"DECEMBER, YEAR 70\n\nFinal note before the exodus to Utopia. The havens failed. The labs did not do their jobs. We did not do ours. We had such hopes that the Faded could hold the world together. But the havens end \"not with a bang, but with a whimper.\" I feel pity for those we leave behind on the havens. They will be lost without us but the fate of the world lies in our hands, not theirs. To Utopia we march.\n\nTo salvation.","footer":"Keep papers like this in the reserve.","stopOrPause":""},"boxes":[]},"12-03":{"title":"New Priorities","category":"legacy_instruction","a":{"header":"KEEP DRAWING","trigger":"","text":"Draw and read the other side of this card.","footer":"","stopOrPause":"CONTINUE"},"b":{"header":"NEW PRIORITIES","trigger":"","text":"DESTROY THE FOLLOWING CARDS IF YOU HAVE NOT DONE SO ALREADY:\n• COMPLETE THE PLAN\n• THE PLAN\n\nA new mandatory objective is enclosed.\nWe only need to complete this 1 objective in December.\n\nCalendar: DECEMBER 1 star, 0.","footer":"","stopOrPause":""},"boxes":[]},"12-04":{"title":"Deliver the Sample","category":"objective","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"MANDATORY OBJECTIVE","trigger":"","text":"Deliver the Sample.\n\nThis objective is completed when:\n• a player carrying the sample is in Johannesburg,\nAND\n• Johannesburg has a supply center.\n\nThis is your last Objective card.\nIf you complete it, you win the game.","footer":"This is your last Objective card. If you complete it, you win the game.","stopOrPause":""},"boxes":[]},"12-05":{"title":"At Last","category":"legacy_stop","a":{"header":"STOP","trigger":"DRAW THIS CARD AFTER STEP 4 OF THE GAME END IF YOU WIN IN DECEMBER OR LOSE YOUR SECOND GAME IN DECEMBER.","text":"STOP\n\nDRAW THIS CARD AFTER STEP 4 OF THE GAME END IF YOU WIN IN DECEMBER OR LOSE YOUR SECOND GAME IN DECEMBER.","footer":"","stopOrPause":"STOP"},"b":{"header":"AT LAST","trigger":"","text":"It's over. The fate of humanity was in your hands.\n\nLook at the following two cards to see what happens next, then calculate your score to determine the ultimate fate of your world.","footer":"","stopOrPause":""},"boxes":[]},"12-06":{"title":"If You Failed to Deliver the Sample","category":"ending","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"IF YOU FAILED TO DELIVER THE SAMPLE...","trigger":"","text":"IF YOU FAILED TO DELIVER THE SAMPLE...\n\nWe have failed to save our people. Without the supplies and the sample, the Faded living in the havens will die.\n\nWe did not choose to have this disease.\n\nWe shall soon be gone. Only the non-Faded humans of Utopia will be left to repopulate the earth.\n\nIf you are reading this, we want you to know that we, the Faded, were not monsters; we were people. Our time was brief and we inadvertently brought much pain to the world.\n\nPlease remember us.","footer":"","stopOrPause":""},"boxes":[]},"12-07":{"title":"If You Delivered the Sample","category":"ending","a":{"header":"","trigger":"","text":"","footer":"","stopOrPause":"NONE"},"b":{"header":"IF YOU DELIVERED THE SAMPLE...","trigger":"","text":"IF YOU DELIVERED THE SAMPLE...\n\nThe sample has been extracted from the carrier; we will always remember their sacrifice. Production will start within days. Utopia’s plan of exterminating us is over. The world belongs to Faded and non-Faded now. They waited for us to die but we survived.\n\nWe are here to stay.","footer":"","stopOrPause":""},"boxes":[]},"12-08":{"title":"The Final Reckoning","category":"legacy_instruction","a":{"header":"","trigger":"","text":"Turn this card over to calculate your final score.","footer":"","stopOrPause":"NONE"},"b":{"header":"THE FINAL RECKONING","trigger":"","text":"Games Won: 50 points per game won in the first half of the month. 30 points per game won in the second half of the month.\nPopulation: Total population of all locations on the grid.\nBonuses: 100 points for delivering the sample. 25 points for each lab on the board.\nSubtotal: Games Won + Population + Bonuses.\nPenalties: -5 points for each forsaken city on the grid.\nGrand Total: Subtotal - Penalties.","footer":"","stopOrPause":""},"boxes":[]},"12-09":{"title":"Did Not Deliver: 851 and Above","category":"ending","a":{"header":"","trigger":"","text":"If you failed to deliver the sample, check your score to determine the fate of the world...","footer":"","stopOrPause":"NONE"},"b":{"header":"DID NOT DELIVER: 851 AND ABOVE","trigger":"","text":"DID NOT DELIVER: 851 AND ABOVE\nWe saved the world, just not ourselves. The 21st century will be remembered as a time of darkness but there is now light ahead. Utopia has the cure and will now produce it at JADE. They just won’t give it to us. The Hollow Men have been freed. The Faded won’t be here to see this new world but we hope that history will remember us as its saviors.\n\nDID NOT DELIVER: 701-850\nWe have persevered. Some cities were saved. Civilization has been rekindled. Utopia and the Hollow Men are at war with each other. One of them will bring the sample to JADE and start producing a cure. We don’t expect either to share it with us. All we know is that we kept the world going when everyone else had given up.","footer":"","stopOrPause":""},"boxes":[]},"12-10":{"title":"Did Not Deliver: 551-700","category":"ending","a":{"header":"DID NOT DELIVER: 551-700","trigger":"","text":"DID NOT DELIVER: 551-700\nDespite our inexperience, we did the impossible. The world has paid the price of our leaders’ fear, Utopia’s malice, and the Hollow Men’s savagery. We are paying the price for failing to get the sample. We believe that the world will recover in time. There will be new cities and new countries. We hope they remember what we did.\n\nDID NOT DELIVER: 401-550\nThe world is a disaster. There is rioting, anarchy, near collapse. Without Utopia in the east, those cities have risen up. We have no cure. We’re not sure the world would survive long enough to use it. Some cities will make it. We hope the world can rebuild from there. We will be gone soon.","footer":"","stopOrPause":"NONE"},"b":{"header":"DID NOT DELIVER: 400 AND BELOW","trigger":"","text":"DID NOT DELIVER: 400 AND BELOW\n\"I hope someone finds this note. The mistrust between Faded and normal humans was too much for the world. We were overwhelmed. Utopia may save the humans...but not us. Our efforts were great but the burden was too heavy. We tried. We failed.\" – Found in ruins of North Atlantic Haven","footer":"","stopOrPause":""},"boxes":[]},"12-11":{"title":"Delivered: 851 and Above","category":"ending","a":{"header":"","trigger":"","text":"If you delivered the sample, check your score to determine the fate of the world...","footer":"","stopOrPause":"NONE"},"b":{"header":"DELIVERED: 851 AND ABOVE","trigger":"","text":"DELIVERED: 851 AND ABOVE\nOur work brought the world back from disaster! Cities are growing. People have hope. Our leaders lost faith but we never did. The 21st century will be remembered as a time of darkness, but there is now light ahead. The Hollow Men have been freed. We, the Faded, are finally free from our exile on the havens.\n\nDELIVERED: 701-850\nWe have persevered. Some cities were saved. Civilization has been rekindled. Faded, non-Faded, Hollow Men: we hope to find a way to co-exist. The world will move on, hopefully for the better, although some cities may never recover.","footer":"","stopOrPause":""},"boxes":[]},"12-12":{"title":"Delivered: 551-700","category":"ending","a":{"header":"DELIVERED: 551-700","trigger":"","text":"DELIVERED: 551-700\nDespite our inexperience, we did the impossible. The world has paid the price of our leaders’ fear, Utopia’s malice, and the Hollow Men’s savagery. But we have a cure! We believe that the world will recover in time. There will be new cities and new countries. Who knows how long it will take to rebuild, but we will be part of it.\n\nDELIVERED: 401-550\nWe didn’t want to be back on the front lines so soon, but the world is a disaster. There is rioting, anarchy, near collapse. Without Utopia in the east, those cities have risen up. We have a cure but we’re not sure the world will survive long enough to use it. Some cities will make it. We hope the world can rebuild from there.","footer":"","stopOrPause":"NONE"},"b":{"header":"DELIVERED: 400 AND BELOW","trigger":"","text":"DELIVERED: 400 AND BELOW\n\"I hope someone finds this note. The mistrust between Faded and normal humans was too much for the world. We were overwhelmed. There is a cure but it may be too little, too late. Our efforts were great but the burden was too heavy. We tried. We tried.\" – Found in ruins of North Atlantic Haven","footer":"","stopOrPause":""},"boxes":[]},"12-13":{"title":"End of the Legacy Deck","category":"end_marker","a":{"header":"CONGRATULATIONS!","trigger":"","text":"CONGRATULATIONS!\n\nYou have reached the end of the Legacy deck for Pandemic Legacy: Season 2. We hope you enjoyed the experience. For the latest updates and community info, visit www.ZManGames.com.","footer":"","stopOrPause":"NONE"},"b":{"header":"WARNING!","trigger":"","text":"WARNING!\n\nTHIS IS THE END OF THE LEGACY DECK.\nPLEASE START FROM THE OTHER SIDE OF THE DECK.","footer":"","stopOrPause":""},"boxes":[]}};
